-- Frozen differential fixtures generated from real NumPy 2.3.5
local np=require("luaray_core")
assert(np._version=="0.111.0-dev")
local checks,cases=0,0
local function deep(a,b,desc)
    assert(type(a)==type(b),desc..': type mismatch: '..type(a)..' vs '..type(b))
    if type(a)=='table' then
        assert(#a==#b,desc..': length mismatch: '..#a..' vs '..#b)
        for i=1,#a do deep(a[i],b[i],desc..'['..i..']') end
    else
        assert(a==b,desc..': '..tostring(a)..' vs '..tostring(b))
    end
    checks=checks+1
end
do
local r=np.random.default_rng(42)
local x=np.flip(np.astype(np.arange(8,"int64"):reshape({2,1,4}),"int64"),1)
local before=x:tolist()
local y=r:permuted(x,1,x)
deep(y.dtype,"int64","42/(2, 1, 4)/int64/flip/0/out_same dtype")
deep(y:tolist(),{{{0,5,6,7}},{{4,1,2,3}}},"42/(2, 1, 4)/int64/flip/0/out_same values")
deep(x:tolist(),{{{0,5,6,7}},{{4,1,2,3}}},"42/(2, 1, 4)/int64/flip/0/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"dbcd12c26eda1624","42/(2, 1, 4)/int64/flip/0/out_same pcg")
cases=cases+1; end
