local x=np.transpose(np.astype(np.arange(8,"int64"):reshape({2,1,4}),"int32"),{3,2,1})
local before=x:tolist()
local out=np.zeros({4,1,2},"int32")
local y=r:permuted(x,3,out)
deep(y.dtype,"int32","42/(2, 1, 4)/int32/transpose/2/out_new dtype")
deep(y:tolist(),{{{4,0}},{{1,5}},{{2,6}},{{3,7}}},"42/(2, 1, 4)/int32/transpose/2/out_new values")
deep(x:tolist(),{{{0,4}},{{1,5}},{{2,6}},{{3,7}}},"42/(2, 1, 4)/int32/transpose/2/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"dbcd12c26eda1624","42/(2, 1, 4)/int32/transpose/2/out_new pcg")
cases=cases+1; end
